### generator.ts
This is the big one. It needs to:
1. Register Handlebars partials
2. Compile layouts
3. Render individual pages
4. Generate tag index pages
5. Generate RSS feed
6. Write HTML files to output

```typescript
import { mkdir, writeFile, readFile, readdir, copyFile } from 'node:fs/promises';
import { join, dirname, extname, basename } from 'node:path';
import Handlebars from 'handlebars';
import type { Page, SiteConfig, TagIndex } from './types.js';

export async function generateSite(pages: Page[], config: SiteConfig): Promise<void> {
  await mkdir(config.outputDir, { recursive: true });

  // Load and register partials
  const partialsDir = join(config.templateDir, 'partials');
  try {
    const partialFiles = await readdir(partialsDir);
    for (const file of partialFiles) {
      if (extname(file) === '.hbs' || extname(file) === '.handlebars') {
        const name = basename(file, extname(file));
        const content = await readFile(join(partialsDir, file), 'utf-8');
        Handlebars.registerPartial(name, content);
      }
    }
  } catch {
    // partials directory may not exist
  }

  // Load layout
  const layoutContent = await readFile(join(config.templateDir, 'layout.hbs'), 'utf-8');
  const layoutTemplate = Handlebars.compile(layoutContent);

  // Load page template
  const pageTemplateContent = await readFile(join(config.templateDir, 'page.hbs'), 'utf-8');
  const pageTemplate = Handlebars.compile(pageTemplateContent);

  // Register a helper to render body within layout
  // Actually, let me think about this differently.
  // The layout wraps the content. The layout has {{{body}}}.
  // The page template renders the page content.
  // So we first render the page template to get the body, then render the layout with that body.

  // Render individual pages
  const publishedPages = pages.filter(p => !p.frontmatter.draft).sort((a, b) => {
    const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
    const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
    return db - da;
  });

  for (const page of publishedPages) {
    const body = pageTemplate({
      page,
      pages: publishedPages,
      site: { title: config.siteTitle, description: config.siteDescription },
    });
    const html = layoutTemplate({
      body,
      page,
      pages: publishedPages,
      site: { title: config.siteTitle, description: config.siteDescription },
    });
    const outPath = join(config.outputDir, page.url.replace(/^\//, ''));
    await mkdir(dirname(outPath), { recursive: true });
    await writeFile(outPath, html);
  }

  // Render index page
  try {
    const indexContent = await readFile(join(config.templateDir, 'index.hbs'), 'utf-8');
    const indexTemplate = Handlebars.compile(indexContent);
    const indexBody = indexTemplate({
      pages: publishedPages,
      site: { title: config.siteTitle, description: config.siteDescription },
    });
    const indexHtml = layoutTemplate({
      body: indexBody,
      page: { frontmatter: { title: config.siteTitle || 'Home' }, url: '/index.html' },
      pages: publishedPages,
      site: { title: config.siteTitle, description: config.siteDescription },
    });
    await writeFile(join(config.outputDir, 'index.html'), indexHtml);
  } catch {
    // index template is optional
  }

  // Generate tag pages
  const tagMap = new Map<string, Page[]>();
  for (const page of publishedPages) {
    if (page.frontmatter.tags) {
      for (const tag of page.frontmatter.tags) {
        if (!tagMap.has(tag)) tagMap.set(tag, []);
        tagMap.get(tag)!.push(page);
      }
    }
  }

  const tagsDir = join(config.outputDir, 'tags');
  await mkdir(tagsDir, { recursive: true });

  try {
    const tagTemplateContent = await readFile(join(config.templateDir, 'tag.hbs'), 'utf-8');
    const tagTemplate = Handlebars.compile(tagTemplateContent);

    for (const [tag, tagPages] of tagMap) {
      const tagBody = tagTemplate({
        tag,
        pages: tagPages,
        site: { title: config.siteTitle },
      });
      const tagHtml = layoutTemplate({
        body: tagBody,
        page: { frontmatter: { title: `Tag: ${tag}` }, url: `/tags/${tag}.html` },
        pages: publishedPages,
        site: { title: config.siteTitle },
      });
      await writeFile(join(tagsDir, `${tag}.html`), tagHtml);
    }
  } catch {
    // tag template is optional
  }

  // Generate RSS feed
  if (config.siteUrl) {
    const rss = generateRSS(publishedPages, config);
    await writeFile(join(config.outputDir, 'feed.xml'), rss);
  }

  // Generate tag index page
  // ...
}

function generateRSS(pages: Page[], config: SiteConfig): string {
  const items = pages.slice(0, 20).map(p => {
    const date = p.frontmatter.date ? new Date(p.frontmatter.date).toUTCString() : new Date().toUTCString();
    return `<item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${config.siteUrl}${p.url}</link>
      <guid>${config.siteUrl}${p.url}</guid>
      <pubDate>${date}</pubDate>
      <description>${escapeXml(p.html.substring(0, 500))}</description>
    </item>`;
  }).join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>${escapeXml(config.siteTitle || 'Site')}</title>
    <link>${config.siteUrl}</link>
    <description>${escapeXml(config.siteDescription || '')}</description>
    ${items}
  </channel>
</rss>`;
}

function escapeXml(s: string): string {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
