### server.ts
```typescript
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
import { WebSocketServer, WebSocket } from 'ws';
import { watch } from 'chokidar';
import type { SiteConfig } from './types.js';

const RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host + '/__reload');
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') location.reload();
    };
    ws.onclose = function() {
      setTimeout(function() {
        location.reload();
      }, 2000);
    };
  })();
</script>
</body>`;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.xml': 'application/xml',
};

export async function startDevServer(config: SiteConfig, port: number, buildFn: () => Promise<void>): Promise<void> {
  const server = createServer(async (req, res) => {
    const url = new URL(req.url || '/', `http://localhost:${port}`);
    let filePath = join(config.outputDir, url.pathname === '/' ? 'index.html' : url.pathname);

    // Remove leading slash for join
    // Actually, join handles this fine

    try {
      let content = await readFile(filePath);
      const ext = extname(filePath);
      const contentType = MIME_TYPES[ext] || 'application/octet-stream';

      if (ext === '.html') {
        // Inject reload script
        const html = content.toString('utf-8');
        const injected = html.replace('</body>', RELOAD_SCRIPT);
        content = Buffer.from(injected);
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    } catch {
      res.writeHead(404);
      res.end('Not Found');
    }
  });

  const wss = new WebSocketServer({ server });

  let clients: WebSocket[] = [];
  wss.on('connection', (ws) => {
    clients.push(ws);
    ws.on('close', () => {
      clients = clients.filter(c => c !== ws);
    });
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });

  // Watch for changes
  const watcher = watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });

  watcher.on('all', async (event, path) => {
    console.log(`File ${event}: ${path}`);
    try {
      await buildFn();
      const reloadMsg = JSON.stringify('reload');
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send('reload');
        }
      }
    } catch (err) {
      console.error('Build error:', err);
    }
  });

  // Graceful shutdown
  process.on('SIGINT', () => {
    watcher.close();
    server.close();
    process.exit(0);
  });
}
```

