        const list = tagMap.get(tag) || [];
        list.push(page);
        tagMap.set(tag, list);
      }
    }
  }

  if (tagMap.size > 0) {
    const tagsDir = join(config.outputDir, 'tags');
    await mkdir(tagsDir, { recursive: true });

    try {
      const tagSrc = await readFile(
        join(config.templateDir, 'tag.hbs'),
        'utf-8',
      );
      const tagTemplate = Handlebars.compile(tagSrc);

      for (const [tag, tagPages] of tagMap) {
        const tagBody = tagTemplate(
          buildCtx({ tag, pages: tagPages, site }),
        );
        const tagHtml = layoutTemplate(
          buildCtx({
            body: tagBody,
            page: {
              path: '',
              frontmatter: { title: `Tag: ${tag}` },
              content: '',
              html: '',
              url: `/tags/${tag}.html`,
            },
            pages: published,
            site,
          }),
        );
        await writeFile(join(tagsDir, `${tag}.html`), tagHtml);
      }
    } catch {
      // tag template is optional
    }
  }

  // RSS feed
  if (config.siteUrl) {
    const rss = generateRSS(published, config);
    await writeFile(join(config.outputDir, 'feed.xml'), rss);
  }

  // copy static assets from source (non-.md files)
  await copyAssets(config.sourceDir, config.outputDir);
}

function sortByDate(a: Page, b: Page): number {
  const da = a.frontmatter.date ? new Date(a.frontmatter.date).getTime() : 0;
  const db = b.frontmatter.date ? new Date(b.frontmatter.date).getTime() : 0;
  return db - da;
}

function buildCtx(overrides: Partial<TemplateContext>): TemplateContext {
  return {
    pages: [],
    site: {},
    ...overrides,
  };
}

function generateRSS(pages: Page[], config: SiteConfig): string {
  const items = pages
    .slice(0, 20)
    .map((p) => {
      const date = p.frontmatter.date
        ? new Date(p.frontmatter.date).toUTCString()
        : new Date().toUTCString();
      return `<item>
      <title>${escapeXml(p.frontmatter.title)}</title>
      <link>${config.siteUrl}${p.url}</link>
      <guid>${config.siteUrl}${p.url}</guid>
      <pubDate>${date}</pubDate>
      <description>${escapeXml(p.html.substring(0, 500))}</description>
    </item>`;
    })
    .join('\n');

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom">
  <channel>
    <title>${escapeXml(config.siteTitle || 'Site')}</title>
    <link>${config.siteUrl}</link>
    <description>${escapeXml(config.siteDescription || '')}</description>
    <atom:link href="${config.siteUrl}/feed.xml" rel="self" type="application/rss+xml"/>
    ${items}
  </channel>
</rss>`;
}

function escapeXml(s: string): string {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

async function copyAssets(
  sourceDir: string,
  outputDir: string,
): Promise<void> {
  try {
    const entries = await readdir(sourceDir, { withFileTypes: true });
    for (const entry of entries) {
      const srcPath = join(sourceDir, entry.name);
      if (entry.isDirectory()) {
        const destDir = join(outputDir, entry.name);
        await mkdir(destDir, { recursive: true });
        await copyAssets(srcPath, destDir);
      } else if (!entry.name.endsWith('.md')) {
        await cp(srcPath, join(outputDir, entry.name));
      }
    }
  } catch {
    // source directory may not have assets
  }
}

import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';
import { WebSocketServer, WebSocket } from 'ws';
import { watch } from 'chokidar';
import type { SiteConfig } from './types.js';

const RELOAD_SCRIPT = `
<script>
  (function() {
    var ws = new WebSocket('ws://' + location.host + '/__reload');
    ws.onmessage = function(msg) {
      if (msg.data === 'reload') location.reload();
    };
    ws.onclose = function() {
      setTimeout(function() { location.reload(); }, 2000);
    };
  })();
</script>
</body>`;

const MIME_TYPES: Record<string, string> = {
  '.html': 'text/html; charset=utf-8',
  '.css': 'text/css',
  '.js': 'application/javascript',
  '.json': 'application/json',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml',
  '.xml': 'application/xml',
  '.ico': 'image/x-icon',
};

export async function startDevServer(
  config: SiteConfig,
  port: number,
  buildFn: () => Promise<void>,
): Promise<void> {
  const server = createServer(async (req, res) => {
    const url = new URL(req.url || '/', `http://localhost:${port}`);
    const filePath = join(
      config.outputDir,
      url.pathname === '/' ? 'index.html' : url.pathname,
    );

    try {
      let content = await readFile(filePath);
      const ext = extname(filePath);
      const contentType = MIME_TYPES[ext] || 'application/octet-stream';

      if (ext === '.html' || ext === '.htm') {
        const html = content.toString('utf-8');
        if (!html.includes('/__reload')) {
          const injected = html.replace('</body>', RELOAD_SCRIPT);
          content = Buffer.from(injected, 'utf-8');
        }
      }

      res.writeHead(200, { 'Content-Type': contentType });
      res.end(content);
    } catch {
      if (url.pathname === '/__reload') {
        res.writeHead(200);
        res.end();
        return;
      }
      res.writeHead(404);
      res.end('Not Found');
    }
  });

  const wss = new WebSocketServer({ server, path: '/__reload' });

  const clients = new Set<WebSocket>();
  wss.on('connection', (ws) => {
    clients.add(ws);
    ws.on('close', () => clients.delete(ws));
  });

  server.listen(port, () => {
    console.log(`Dev server running at http://localhost:${port}`);
  });

  const watcher = watch([config.sourceDir, config.templateDir], {
    ignoreInitial: true,
  });

  const rebuild = async (event: string, path: string) => {
    console.log(`[${event}] ${path}`);
    try {
      await buildFn();
      for (const client of clients) {
        if (client.readyState === WebSocket.OPEN) {
          client.send('reload');
        }
      }
    } catch (err) {
      console.error('Build error:', err);
    }
  };

  watcher.on('add', (p) => rebuild('add', p));
  watcher.on('change', (p) => rebuild('change', p));
  watcher.on('unlink', (p) => rebuild('unlink', p));

  process.on('SIGINT', () => {
    watcher.close();
    wss.close();
    server.close();
    process.exit(0);
  });
}

#!/usr/bin/env node
import { Command } from 'commander';
import { parseMarkdownFiles } from './parser.js';
import { generateSite } from './generator.js';
import { startDevServer } from './server.js';
import type { SiteConfig } from './types.js';

const program = new Command();

program
  .name('ssg')
  .description('Static site generator from Markdown and Handlebars templates')
  .version('1.0.0')
  .requiredOption('-s, --source <dir>', 'Source directory of markdown files')
  .requiredOption('-t, --templates <dir>', 'Template directory')
  .requiredOption('-o, --output <dir>', 'Output directory')
  .option('--site-title <title>', 'Site title')
  .option('--site-url <url>', 'Site URL (enables RSS feed generation)')
  .option('--site-description <desc>', 'Site description')
  .option('--serve', 'Start dev server with live reload')
  .option('-p, --port <port>', 'Dev server port', '3000')
  .action(async (options) => {
    const config: SiteConfig = {
      sourceDir: options.source,
      templateDir: options.templates,
      outputDir: options.output,
      siteTitle: options.siteTitle,
      siteUrl: options.siteUrl,
      siteDescription: options.siteDescription,
    };

    const build = async () => {
      const pages = await parseMarkdownFiles(config.sourceDir);
      await generateSite(pages, config);
      console.log(`Built ${pages.length} pages to ${config.outputDir}`);
    };

    await build();

    if (options.serve) {
      await startDevServer(config, parseInt(options.port, 10), build);
    }
  });

program.parse();

